INSERT INTO workflow_definition (tenant_id, id, display_name, description, mode, enabled, active_version, source) VALUES ('default', 'finance-smart', '报销智能分析', '对照制度分析当前用户报销单是否合规（含 Agent 推理）', 'workflow', 1, 1, 'seed');
INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'finance-smart', 1, 'published', '{"planId":null,"reason":"导入自 sunshine-workflows.yaml · finance-smart","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"tool-d4e8f901","type":"tool","displayName":"查询我的报销单","params":{"tool":"sdk__sunshine-finance__list_my_expenses","status":"{{plan.params.status}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"agent-b2c6d803","type":"agent","displayName":"智能体分析","params":{"query":"{{start.userQuery}}","context":"{{tool-d4e8f901.output}}","skill":"finance-analysis","tools":"sdk__sunshine-finance__list_my_expenses","maxIters":"4","systemOverlay":"本节点仅输出内部分析结论，不面向用户；禁止调用白名单外工具","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"根据 Agent 分析结果生成用户可见回答。\\n\\n约束：禁止向用户暴露英文流程/工具内部名（如 finance-smart、finance-list）。\\n\\n分析：\\n{{agent-b2c6d803.answer}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"tool-d4e8f901"},{"from":"tool-d4e8f901","to":"agent-b2c6d803"},{"from":"agent-b2c6d803","to":"answer"}],"layout":{"start":{"x":48,"y":72},"tool-d4e8f901":{"x":268,"y":72},"agent-b2c6d803":{"x":488,"y":72},"answer":{"x":708,"y":72}}}', '{"examples":["待审批报销是否合规","对比制度与待办"],"nodeSummary":["start","tool","agent","answer"]}', CURRENT_TIMESTAMP);

