INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'finance-summary', 1, 'published', '{"planId":null,"reason":"导入自 sunshine-workflows.yaml · finance-summary","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"tool-a9c1e502","type":"tool","displayName":"汇总我的报销","params":{"tool":"sdk__sunshine-finance__summarize_my_expenses","status":"{{plan.params.status}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"根据财务汇总工具结果回答用户。\\n\\n约束：禁止向用户暴露英文流程/工具内部名。\\n\\n汇总：\\n{{tool-a9c1e502.output}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"tool-a9c1e502"},{"from":"tool-a9c1e502","to":"answer"}],"layout":{"start":{"x":48,"y":72},"tool-a9c1e502":{"x":268,"y":72},"answer":{"x":488,"y":72}}}', '{"examples":["待审批有多少条","pending 财务总额"],"nodeSummary":["start","tool","answer"]}', CURRENT_TIMESTAMP);

