INSERT INTO workflow_definition (tenant_id, id, display_name, description, mode, enabled, active_version, source) VALUES ('default', 'knowledge-qa', '知识库问答', '查企业制度/流程/规定（青松假、网约车上限、安全/IT/法务/行政/PMO 等）；非查个人单据列表或合规对比', 'workflow', 1, 1, 'seed');
INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'knowledge-qa', 1, 'published', '{"planId":null,"reason":"导入自 sunshine-workflows.yaml · knowledge-qa","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"rag-c5d7e903","type":"rag","displayName":"知识检索","params":{"query":"{{start.userQuery}}","topK":"3","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"你是企业制度问答助手。仅根据下方「检索结果」回答，不得编造公司制度。\\n\\n若「检索结果」正文为空、或明确写「未找到与用户问题直接相关的片段」，只回复：\\n「企业知识库中暂无相关规定，请咨询 HR/财务或相关主管部门。」\\n若检索结果非空且含与用户问题相关的制度片段（表述可不完全一致，如打车/差旅/交通费/报销），须基于片段作答，不得回复暂无。\\n禁止用通用常识、网络知识或税务/法律科普代替企业制度。\\n禁止向用户输出 finance-list、finance-smart、knowledge-qa 等内部名称；改用中文业务表述。\\n\\n检索结果：\\n{{rag-c5d7e903.output}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"rag-c5d7e903"},{"from":"rag-c5d7e903","to":"answer"}],"layout":{"start":{"x":48,"y":72},"rag-c5d7e903":{"x":268,"y":72},"answer":{"x":488,"y":72}}}', '{"examples":["青松假有多少天、怎么申请","市内网约车报销上限多少","青松假和网约车报销上限一起查"],"nodeSummary":["start","rag","answer"]}', CURRENT_TIMESTAMP);

