INSERT INTO workflow_definition (tenant_id, id, display_name, description, mode, enabled, active_version, source) VALUES ('default', 'knowledge-loop', '条件循环知识检索', 'do-while：首轮必进框内 rag→tool→agent；含「继续」则再轮（最多 2，超限 exit）（4.13.7）', 'workflow', 1, 1, 'seed');
