"x":200,"y":40,"width":560,"height":160},"rag-l1o2o3p4":{"x":224,"y":92},"tool-t1o2o3p4":{"x":412,"y":92},"agent-a1g2e3n4":{"x":600,"y":92},"answer":{"x":820,"y":72}}}', '{"examples":["分析青松假余额和我的待报销","继续分析青松假余额和我的待报销"],"nodeSummary":["start","loop","rag","tool","agent","answer"],"intentAfter":"将按条件循环（检索→工具→智能体）流程处理"}', CURRENT_TIMESTAMP);

-- sandbox-agent（4.5 SUB 默认沙箱标杆：agent 节点写 /workspace）
INSERT INTO workflow_definition (tenant_id, id, display_name, description, mode, enabled, active_version, source) VALUES ('default', 'sandbox-agent', '沙箱子 Agent 写文件', 'Workflow agent 节点默认沙箱：用 sandbox__* 在对话工作区写文件后汇总（4.5 SUB 默认沙箱标杆）', 'workflow', 1, 1, 'seed');
INSERT INTO workflow_version (tenant_id, workflow_id, version, status, plan_json, catalog_meta, published_at) VALUES ('default', 'sandbox-agent', 1, 'published', '{"planId":null,"reason":"4.5 SUB 默认沙箱标杆（start→agent→answer；复用对话级 /workspace）","nodes":[{"id":"start","type":"start","displayName":"开始","params":{}},{"id":"agent-s4b0x7a1","type":"agent","displayName":"沙箱写文件","params":{"query":"{{start.userQuery}}","context":"请在对话沙箱 /workspace 完成用户请求的文件写入；沙箱六工具已注入，无需 Catalog 白名单。","maxIters":"4","systemOverlay":"本节点为 Workflow 子 Agent，仅输出内部结论供下游润色。\\n必须使用 sandbox__write（新建）或 sandbox__edit（已存在）在 /workspace 落盘；过渡语后立刻 tool call。\\n禁止编造「已写入」而未实际调用工具；完成后用简短中文说明路径与要点。","retry.maxAttempts":"1","retry.backoffMs":"500","retry.onFailure":"continue"}},{"id":"answer","type":"answer","displayName":"回答","params":{"prompt":"根据子 Agent 结论生成用户可见回答。\\n\\n约束：禁止暴露 sandbox-agent、sandbox__* 等内部名；用中文说明已写入的工作区文件路径与内容要点。\\n\\n子 Agent 结论：\\n{{agent-s4b0x7a1.answer}}","retry.maxAttempts":"2","retry.backoffMs":"500","retry.onFailure":"fail_fast"}}],"edges":[{"from":"start","to":"agent-s4b0x7a1"},{"from":"agent-s4b0x7a1","to":"answer"}],"layout":{"start":{"x":48,"y":72},"agent-s4b0x7a1":{"x":268,"y":72},"answer":{"x":488,"y":72}}}', '{"examples":["在工作区写一份 hello.txt 内容为 hello sandbox","用沙箱新建 /workspace/note.md"],"nodeSummary":["start","agent","answer"],"intentAfter":"将按沙箱子 Agent 写文件流程处理"}', CURRENT_TIMESTAMP);
